import { describe, expect, test } from "bun:test";

import vectors from "./vectors.json";
import { buildFrame, FrameError, parseResponse } from "../src/elitech/frame.js";
import {
  decodeInfo,
  encodeInterval,
  ParameterImage,
} from "../src/elitech/parameters.js";
import { decodeRecord } from "../src/elitech/records.js";

describe("request frames match python-elitech byte for byte", () => {
  for (const v of vectors.frames) {
    const arg = v.payload ? Uint8Array.from(v.payload) : v.count;
    test(`op 0x${v.op.toString(16)} offset ${v.offset}`, () => {
      expect(Array.from(buildFrame(v.op, v.offset, arg))).toEqual(v.expected);
    });
  }
});

describe("response parsing matches python-elitech", () => {
  for (const v of vectors.responses) {
    test(`op 0x${v.op.toString(16)} offset ${v.offset} count ${v.count}`, () => {
      const result = parseResponse(v.op, v.offset, v.count, Uint8Array.from(v.answer));
      if (typeof v.expected === "boolean") {
        expect(result).toBe(v.expected);
      } else {
        expect(Array.from(result)).toEqual(v.expected);
      }
    });
  }

  test("rejects a corrupted checksum", () => {
    const v = vectors.responses[0];
    const answer = Uint8Array.from(v.answer);
    answer[answer[3] - 1] ^= 0xff;
    expect(() => parseResponse(v.op, v.offset, v.count, answer)).toThrow(FrameError);
  });

  test("rejects an answer for a different offset", () => {
    const v = vectors.responses[0];
    expect(() =>
      parseResponse(v.op, v.offset + 1, v.count, Uint8Array.from(v.answer)),
    ).toThrow(FrameError);
  });
});

describe("record decoding matches python-elitech", () => {
  for (const [i, v] of vectors.records.entries()) {
    test(`record ${i}`, () => {
      const r = decodeRecord(Uint8Array.from(v.bytes), v.protocol);
      if (v.empty) {
        expect(r).toBeNull();
        return;
      }
      expect(r.time).toBe(v.time);
      expect(r.temperature).toBeCloseTo(v.temperature, 10);
      expect(r.mark).toBe(v.mark);
      expect(r.pause).toBe(v.pause);
      expect(r.stop).toBe(v.stop);
      expect(r.error).toBe(v.error);
    });
  }
});

describe("parameter decoding matches python-elitech", () => {
  for (const [i, v] of vectors.parameters.entries()) {
    test(`memory image ${i}`, () => {
      const image = new ParameterImage();
      image.add(0, Uint8Array.from(v.memory));
      const info = decodeInfo(image);
      const d = v.decoded;

      expect(info.model).toBe(parseInt(d.model, 16));
      expect(info.serialNumber).toBe(d["serial-number"]);
      expect(info.firmwareVersion).toBe(parseInt(d["firmware-version"], 16));
      expect(info.recordCount).toBe(parseInt(d["record-number"], 16));
      expect(info.deviceCapacity).toBe(parseInt(d["device-capacity"], 16));
      expect(info.intervalSeconds).toBe(d.interval);
      expect(info.configurationTime).toBe(d["configuration-time"]);
      expect(info.deviceTime).toBe(d["device-time"]);
      expect(info.protocolVersion).toBe(parseInt(d["protocol-version"], 16));
      expect(info.timezone).toBe(d.timezone);
    });
  }

  test("interval encoding for 1..15 minutes", () => {
    for (const v of vectors.intervalEncoding) {
      expect(Array.from(encodeInterval(v.seconds))).toEqual(v.bytes);
    }
  });
});
